"""Report of cached gate/initialization/position evidence; no new evaluation."""
import os
os.environ['CUDA_VISIBLE_DEVICES']='';os.environ['MPLBACKEND']='Agg'
from pathlib import Path
import sys,collections
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
import numpy as np
from scripts.run_stvg_joint_event_critic_v1 import read,load,put,sha
from scripts.diagnose_stvg_dino_feedback_cache32_v1 import D,P,verify,export


def main():
    import matplotlib.pyplot as plt
    p=verify();r=read(P/'DIAGNOSIS.json');a=read(P/'ROOT_INDEPENDENT_AUDIT.json');assert a['status']=='pass'
    native=read(P/'MATCHED_NATIVE900_CASE.json');within=read(P/'WITHIN_FIXED_CONTENT.json');raw=load(D/'CACHED_SCALAR_ROWS.pt');nativeprobes=read(P/'NATIVE_RETAINED_PROBE_SUMMARY.json')
    config={k:v for k,v in p.items()if k not in ['records','created_epoch']};config.update(backbone='original TA-STVG frozen Source outputs only, no forward',teacher='original grounded-dino-tiny, static source/config inspection only',prior_measured_commit='2d4a3fa4308a5e4a19fd8dd219deb5f688b4b1fc',new_model_calls=0,new_GT_scores=0,new_predictions=0)
    export(P/'CONFIGURATION.json',config)
    cross={}
    for ds in ['hc2','vidstg']:
        rr=[x for x in raw['anchors']if x['dataset']==ds and x['arm']=='Dynamic3']
        cross[ds]={}
        for band in ['all','native_final_overlap_ge050','native_final_overlap_ge075']:
            sel=rr if band=='all'else[x for x in rr if x['input_native_max_iou']is not None and x['input_native_max_iou']>=(.5 if '050'in band else .75)]
            cross[ds][band]={str(k):dict(count=len([x for x in sel if (x['slot']<10)==k]),accepted=sum(x['accepted']for x in sel if (x['slot']<10)==k))for k in [True,False]}
    export(P/'POSITION_SLOT_CROSSTAB.json',dict(status='descriptive_joint_association',groups=cross,small_number_contexts_not_independent_samples=True,does_not_separate_content_from_reference_causally=True))
    conclusion=dict(status='cached_diagnosis_complete_no_new_run',
        threshold='Direct gate is .35, but scores mostly far below cutoff. No pileup just below .35 and no evidence that releasing low-score outputs would help.',
        content='Nearest initial-reference geometry selects a learned native query-slot row without target-token-support conditioning. All admitted Dynamic3 outputs are slots0-9; many selected rows are later-ranked. This is a selection/position compatibility hypothesis, not proof that later content vectors are intrinsically bad.',
        position='Whole-trajectory legality gate loses77 HC and14 Vid candidate trajectories, but legal/fully visible/high-native-overlap inputs also frequently have low conditional scores. Geometry contributes but is not a complete explanation.',
        matched_case='H018 exact4-frame native900 cache: one native slot/frame passes .35; none of96 fixed or96 dynamic selected slots do so in their original native outputs. Conditional response is already following weakly target-supported native slots, not solely collapsing high-score predictions.',
        causal_limit='No same input reference with alternative content response, no original900 initial-reference or content-vector cache. Cannot partition causal percentages or establish a content replacement fix.',
        admission_not_correctness=True,no_GT_quality_inference=True,no_threshold_recommendation_or_search=True,
        no_new_experiment_or_expansion=True,CURRENT_unchanged=True)
    export(P/'CONCLUSION.json',conclusion)
    lines=['# Conditional DINO feedback scarcity: original32 cached diagnosis','','Same exposed HC16/Vid16 as2d4a3fa4. Existing scalar outputs and reference actions only. No model/decoder/processor forward, pretrained weight load, video/image read, official GT read, GT scoring, new candidate, parameter change or alternative prediction. One-at-E24 repeated actions are collapsed to one reference per original anchor. The word admitted means passing the existing score gate, not verified correct geometry or identity.','','## Direct census of the unchanged .35 gate','','| Domain/arm | Active/16 | Candidate trajectories | Invalid | Legal | With admitted feedback | Returned anchor outputs | Score>=.35 | [.30,.35) | Score median |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
    for ds,gg in r['groups'].items():
        for arm,g in gg.items():
            s=g['anchor_scores'];lines.append(f'| {ds}/{arm} | {g["active_queries"]}/16 | {g["candidate_trajectories"]} | {g["illegal_trajectories"]} | {g["legal_trajectories"]} | {g["legal_trajectories_with_feedback"]} | {s["n"]} | {s["accepted"]} | {s["near_below_030_035"]} | {s["quantiles"]["median"]:.6f} |')
    lines+=['','These are mechanical counts, not a temperature/threshold experiment. HC Dynamic3 has1219 rejected returned outputs and zero in[.30,.35); Vid has986 rejected outputs, only5 in that band. Most HC output scores are around.004 rather than just below.35. A modest cutoff adjustment is not supported by a near-cutoff pileup; no claim is made about the correctness of released low-score boxes. No thresholds or predicted results were changed.','','## What the content initialization actually is','','Installed snapshot config has embedding_init_target=true,two_stage=true,num_queries=900. HF creates a learned query_position_embeddings table and uses its rows as decoder target content. The encoder top900 proposal order is based on maximum logit across text tokens, not the target-token score. The experimental wrapper chooses the nearest initial native proposal by geometry and copies that slot\'s learned embedding. It does not copy a query-specific ROI visual descriptor, nor select by target semantic support. This pairing can be incompatible with the student reference; cached scores alone do not isolate the content vector from its associated proposal.','','| Dynamic domain | Selected slot0-9 / returned | Passed in0-9 | Selected slot10-899 | Passed there | Known original Top3 slot matches | Originally >=.35 among matched | Still pass |','|---|---:|---:|---:|---:|---:|---:|---:|']
    for ds,gg in r['groups'].items():
        g=gg['Dynamic3'];s=g['anchor_scores'];first=g['slot_bands']['000-009'];lines.append(f'| {ds} | {first["n"]}/{s["n"]} | {first["accepted"]} | {s["n"]-first["n"]} | {s["accepted"]-first["accepted"]} | {s["known_original_Top3_slot_matches"]} | {s["original_same_slot_score_ge035"]} | {s["original_same_slot_score_ge035"]-s["original_ge035_but_conditional_below035"]} |')
    lines+=['','Native Top3 IDs are reliable only for context_active=true. Fallback ID0 is a placeholder and was excluded from slot matching. A slot absent from Top3 is unknown, not proven wrong. These within-cache associations do not establish that slot>=10 embeddings are intrinsically defective: proposal rank, geometry and content assignment are coupled.','','## One exact matching full900 cache: H018','','The metadata join found one current-cohort query with old raw native900 output. All four RGB hashes, original text, input tensor hashes, target spans and retained probes exactly match. No other cohort data were added. At its four anchors the native maximum target scores are '+', '.join(f'{x["native_max_score"]:.6f}'for x in native['qualifications'])+'; exactly one of900 native slots per anchor passes.35.','','For H018 fixed24 and Dynamic3, all96 selected slots already have original native target score<.35 (maximum '+f'{native["groups"]["Dynamic3"]["selected_slot_original_native_score"]["quantiles"]["max"]:.6f}'+'). Their median original score is '+f'{native["groups"]["Dynamic3"]["selected_slot_original_native_score"]["quantiles"]["median"]:.6f}'+', versus conditional median '+f'{native["groups"]["Dynamic3"]["conditional_score"]["quantiles"]["median"]:.6f}'+'. Thus this case starts from native slots with weak target support; it is not a case where many originally confident target slots uniformly collapse only after reanchoring. This is one case, not a cohort-wide causal proof. No arbitrary content-swap output exists in cache.','','## Student reference position and legality','','| Dynamic domain | Invalid trajectories | Individual invalid anchor refs | Otherwise legal anchors discarded with bad trajectory | Fully inside returned refs / admitted | Input IoU>=.75 with cached native final pool / admitted |','|---|---:|---:|---:|---:|---:|']
    for ds,gg in r['groups'].items():
        g=gg['Dynamic3'];inside=g['fully_inside_image'];near=g['overlap_native_final_ge075'];lines.append(f'| {ds} | {g["illegal_trajectories"]} | {g["invalid_anchor_references"]} | {g["otherwise_valid_anchor_references_discarded"]} | {inside["n"]}/{inside["accepted"]} | {near["n"]}/{near["accepted"]} |')
    lines+=['','Legality tests every cx,cy,w,h in open(0,1), not whether every corner lies inside the image. The whole trajectory is discarded if any one of its four references fails;129 HC and40 Vid individually legal anchors therefore have no measured conditional output. Their hypothetical feedback is unknown. HC invalid coordinate counts are cx4,cy0,w12,h171 (reasons can overlap), Vid height16 only. No clipping or gate change was tested.','','Position matters descriptively: farther from retained native final boxes, admitted feedback is rarer. Yet1041 fully contained HC inputs yield only4 admitted outputs, and38/44 HC inputs with native-pool overlap>=.75 still fail. Boundary violations or reference distance alone do not explain everything. Native retained boxes are detection proxies, not target GT; matching them is not an identity/correctness label.','','Holding frame/text/selected content slot fixed, unique saved reference changes do alter scores; some groups cross.35. Same-input repeated scores vary at most '+f'{within["same_input_repeated_score_range"]["quantiles"]["max"]:.9f}'+', while within-slot ranges can be much larger. Group counts and score ranges are in WITHIN_FIXED_CONTENT.json. These are dependent samples; no causal variance share or independent-sample confidence interval is claimed.','','## What is and is not established','','The exact loss chain is: no E support -> invalid reference -> low conditional target score -> admitted correction. The gate can be counted exactly. The strongest unresolved interface issue is how geometrically selected native slot/content and the student reference are paired, given their weak native target support. Original DINO decodes its full query pool then selects by text; selecting a geometric slot first changes which evidence is available. This does not prove that a different initialization would work.','','Initial900 reference coordinates, copied content vectors, full native scores for31 other queries and same-reference alternative-content outputs are absent. Therefore content versus position cannot be cleanly divided into causal percentages. All-original clone qualification established engineering replay only, not arbitrary-box target correction. No lowered threshold, new content initialization or new teacher pass was tested; current interface remains stopped.','','## Integrity and cost','','This is CPU-only cache diagnosis, with no new GT metrics or localization performance results. Independent audit verifies every1372 candidate-trajectory census entry,4756 returned scalar references and196 selected-slot matches against the one native900 cache, plus all6 domain/arm summaries. All32 queries and unknown states retained. Source/current method/old prediction pins are unchanged. Public export excludes raw input boxes, original Query/parent strings, GT coordinates, images, weights and original tensors.']
    (P/'REPORT.md').write_text('\n'.join(lines)+'\n');(P/'README.md').write_text('See REPORT.md, DIAGNOSIS.json, CONTENT_AND_CACHE_AVAILABILITY.json, MATCHED_NATIVE900_CASE.json, POSITION_SLOT_CROSSTAB.json, WITHIN_FIXED_CONTENT.json and ROOT_INDEPENDENT_AUDIT.json.\n')
    fig,axs=plt.subplots(1,3,figsize=(15,4.8));fig.subplots_adjust(bottom=.26,wspace=.32)
    for ds,col in [('hc2','#217f88'),('vidstg','#bc7744')]:
        rr=[x['score']for x in raw['anchors']if x['dataset']==ds and x['arm']=='Dynamic3'];ss=np.sort(rr)
        axs[0].plot(ss,np.arange(1,len(ss)+1)/len(ss),c=col,label=ds)
    axs[0].axvline(.35,c='.3',ls='--');axs[0].set_xscale('log');axs[0].set_xlabel('Saved conditional target score (log)');axs[0].set_ylabel('Returned-output empirical CDF');axs[0].legend();axs[0].set_title('Scores far below gate')
    for i,ds in enumerate(['hc2','vidstg']):
        g=r['groups'][ds]['Dynamic3'];values=[g['illegal_trajectories'],g['legal_trajectories_without_feedback'],g['legal_trajectories_with_feedback']];bottom=0
        for v,col,label in zip(values,['#999999','#d7ad6d','#438b88'],['Illegal','Legal, no admitted feedback','Feedback']):
            axs[1].bar(i,v,bottom=bottom,color=col,label=label if i==0 else None);bottom+=v
    axs[1].set_xticks([0,1],['HC','Vid']);axs[1].set_ylabel('Visited candidate trajectories');axs[1].set_title('Whole-trajectory gate');axs[1].legend(fontsize=7)
    labels=[];fail=[];passed=[]
    for ds in ['hc2','vidstg']:
        g=r['groups'][ds]['Dynamic3'];s=g['anchor_scores'];low=g['slot_bands']['000-009']
        labels +=[ds+' 0-9',ds+' 10-899'];passed +=[low['accepted'],s['accepted']-low['accepted']];fail +=[low['n']-low['accepted'],s['n']-low['n']-(s['accepted']-low['accepted'])]
    axs[2].bar(range(4),fail,color='#bcbcbc',label='Below .35');axs[2].bar(range(4),passed,bottom=fail,color='#438b88',label='Admitted');axs[2].set_xticks(range(4),labels,rotation=20);axs[2].set_ylabel('Returned anchor references');axs[2].set_title('Selected native slot ranks');axs[2].legend(fontsize=7)
    fig.text(.06,.04,'Original32 cached states only; no new model or GT evaluation. Slot rank, content and reference geometry are coupled.\nCounts measure admission, not correct localization. No threshold/content change or expansion performed.',fontsize=9)
    review=D/'root_review';review.mkdir(exist_ok=True);fig.savefig(P/'CACHED_FEEDBACK_DIAGNOSIS.svg');fig.savefig(review/'CACHED_FEEDBACK_DIAGNOSIS.png',dpi=140);plt.close(fig)
    export(P/'ACTUAL_COSTS.json',dict(CPU_only=True,cache_analysis_seconds=r['CPU_seconds'],new_model_calls=0,new_GT_scores=0,new_predictions=0,new_expert_frames=0,new_training=0,CUDA_initialized=False))
    own=['vg_tta/stvg_dino_feedback_cache32_v1.py','scripts/diagnose_stvg_dino_feedback_cache32_v1.py','scripts/supplement_stvg_dino_feedback_native900_cache32_v1.py','scripts/audit_stvg_dino_feedback_cache32_v1.py','scripts/report_stvg_dino_feedback_cache32_v1.py','scripts/publish_stvg_dino_feedback_cache32_v1.py','protocols/stvg_dino_feedback_cache32_v1.md']
    names=['DIAGNOSIS.json','CONTENT_AND_CACHE_AVAILABILITY.json','WITHIN_FIXED_CONTENT.json','NATIVE_RETAINED_PROBE_SUMMARY.json','MATCHED_NATIVE900_CASE.json','POSITION_SLOT_CROSSTAB.json','ROOT_INDEPENDENT_AUDIT.json','CONCLUSION.json','CONFIGURATION.json','REPORT.md','README.md','CACHED_FEEDBACK_DIAGNOSIS.svg','ACTUAL_COSTS.json']
    export(D/'PUBLIC_FILES.json',dict(files=own+[str((P/f).relative_to(ROOT))for f in names]));print(dict(status='report_ready',files=len(own)+len(names)))


if __name__=='__main__':main()
